import os
import boto3
from botocore.exceptions import ClientError
from boto3.dynamodb.conditions import Attr, Key
from aws_lambda_powertools import Logger, Tracer
from aws_lambda_powertools.utilities.typing import LambdaContext
import json
from datetime import datetime
import uuid

# Initialize tracer and logger
tracer = Tracer()
logger = Logger()

# Initialize DynamoDB resources
dynamodb = boto3.resource("dynamodb")
cells_table = dynamodb.Table(os.environ["CELLs_TABLE_NAME"])
deployments_table = dynamodb.Table(os.environ["DEPLOYMENTS_TABLE_NAME"])
tenants_table = dynamodb.Table(os.environ["TENANTS_TABLE_NAME"])

# Initialize EventBridge client and configuration
event_bus = boto3.client("events")
eventbus_name = os.environ["EVENTBUS_NAME"]
event_source = os.environ["EVENT_SOURCE"]
tenant_registration_detail_type = os.environ["CELL_MANAGEMENT_DETAIL_TYPE"]

def __create_control_plane_event(event_details, detail_type):
    """Publish events to EventBridge"""
    logger.info(f"Publishing event to EventBridge - DetailType: {detail_type}")
    response = event_bus.put_events(
        Entries=[   
            {
                "EventBusName": eventbus_name,
                "Source": event_source,
                "DetailType": detail_type,
                "Detail": event_details,
            }
        ]
    )
    logger.info(f"Event published successfully: {response}")

def find_available_cell(tier):
    """Find an available cell for the given tier"""
    logger.info(f"Finding available cell for tier: {tier}")
    response = cells_table.scan(
        FilterExpression=Attr('tier').eq(tier)
    )

    cells = response['Items']
    logger.info(f"Found {len(cells)} cells for tier {tier}")
    
    if not cells:
        logger.error(f"No cells available for tier {tier}")
        raise Exception(f"No cells available for tier {tier}")
        
    selected_cell = max(cells, key=lambda x: 
        int(x['totalCapacity']) - int(x['currentCapacity']))
    
    if int(selected_cell['currentCapacity']) >= int(selected_cell['totalCapacity']):
        logger.error(f"No capacity available in cells for tier {tier}")
        raise Exception(f"No capacity available in cells for tier {tier}")
        
    logger.info(f"Selected cell: {selected_cell['cellID']} for tier {tier}")
    return selected_cell

def find_or_create_deployment(cell, tier):
    """Find an available deployment or create a new one based on cell topology"""
    cell_id = cell['cellID']
    topology = cell['topology']
    logger.info(f"Finding/creating deployment for cell {cell_id} with topology {topology} and tier {tier}")
    
    if topology == 'SILOS_PER_CELL':
        logger.info(f"Creating new silo for cell {cell_id} due to SILOS_PER_CELL topology")
        return create_new_silo(cell_id, tier)
    
    if topology == 'SILOS_POOLS_PER_CELL' and tier == 'premium':
        logger.info(f"Creating new silo for premium tier in cell {cell_id}")
        return create_new_silo(cell_id, tier)
    
    logger.info(f"Finding/creating pool for cell {cell_id}")
    return find_or_create_pool(cell_id, tier)

def find_or_create_pool(cell_id, tier):
    """Find an available pool or create a new one"""
    logger.info(f"Searching for available pool in cell {cell_id} for tier {tier}")
    response = deployments_table.query(
        KeyConditionExpression=Key('PK').eq(f'CELL#{cell_id}'),
        FilterExpression=Attr('type').eq('POOL') & 
                        Attr('tier').eq(tier) & 
                        Attr('status').eq('ACTIVE')
    )
    
    pools = response['Items']
    logger.info(f"Found {len(pools)} active pools for cell {cell_id}")
    
    if pools:
        selected_pool = min(pools, 
            key=lambda x: int(x['currentCapacity']))
        
        if int(selected_pool['currentCapacity']) < int(selected_pool['totalCapacity']):
            logger.info(f"Selected existing pool: {selected_pool['deploymentId']}")
            return selected_pool
    
    # Create new pool if no available pools found
    logger.info(f"Creating new pool for cell {cell_id}")
    new_pool = {
        'PK': f'CELL#{cell_id}',
        'SK': f'DEPLOYMENT#pool-{str(uuid.uuid4())}',
        'deploymentId': f'pool-{str(uuid.uuid4())}',
        'type': 'POOL',
        'name': f'pool-{cell_id}-{tier}',
        'totalCapacity': 100,  # Configure based on your needs
        'currentCapacity': 0,
        'tier': tier,
        'status': 'ACTIVE',
        'createdAt': datetime.now().isoformat()
    }
    
    deployments_table.put_item(Item=new_pool)
    logger.info(f"Created new pool: {new_pool['deploymentId']}")
    return new_pool

def create_new_silo(cell_id, tier):
    """Create a new silo deployment"""
    logger.info(f"Creating new silo for cell {cell_id} and tier {tier}")
    new_silo = {
        'PK': f'CELL#{cell_id}',
        'SK': f'DEPLOYMENT#silo-{str(uuid.uuid4())}',
        'deploymentId': f'silo-{str(uuid.uuid4())}',
        'type': 'SILO',
        'name': f'silo-{cell_id}-{tier}',
        'totalCapacity': 1,
        'currentCapacity': 0,
        'tier': tier,
        'status': 'ACTIVE',
        'createdAt': datetime.now().isoformat()
    }
    
    deployments_table.put_item(Item=new_silo)
    logger.info(f"Created new silo: {new_silo['deploymentId']}")
    return new_silo

@logger.inject_lambda_context(log_event=True)
@tracer.capture_lambda_handler
def lambda_handler(event: dict, context: LambdaContext) -> dict:
    """Main Lambda handler function"""
    logger.info("Starting tenant registration process")
    logger.info(f"Received event: {event}")
    
    # Extract tenant information from the event
    detail = event.get('detail', {})
    tenant_id = detail.get("tenantId")
    tier = detail.get("tier")
    tenant_name = detail.get("tenantName")
    registration_status = detail.get("registrationStatus")
    tenant_registration_id = detail.get("tenantRegistrationId")
    email = detail.get("email")

    logger.info(f"Processing registration for tenant {tenant_id} with tier {tier}")

    try:
        # Find available cell
        selected_cell = find_available_cell(tier)
        cell_id = selected_cell['cellID']
        logger.info(f"Selected cell {cell_id} for tenant {tenant_id}")

        # Find or create appropriate deployment
        deployment = find_or_create_deployment(selected_cell, tier)
        deployment_id = deployment['deploymentId']
        logger.info(f"Selected/created deployment {deployment_id} for tenant {tenant_id}")

        # Prepare tenant registration data
        tenant_item = {
            'PK': f'TENANT#{tenant_id}',
            'SK': f'METADATA#{tenant_id}',
            'GSI1PK': f'CELL#{cell_id}',
            'GSI1SK': f'TENANT#{tenant_id}',
            'GSI2PK': f'DEPLOYMENT#{deployment_id}',
            'GSI2SK': f'TENANT#{tenant_id}',
            'tenantId': tenant_id,
            'cellID': cell_id,
            'deploymentId': deployment_id,
            'deploymentType': deployment['type'],
            'deploymentName': deployment['name'],
            'tier': tier,
            'tenantName': tenant_name,
            'email': email,
            'registrationStatus': registration_status,
            'tenantRegistrationId': tenant_registration_id,
            'tenantStatus': 'ACTIVE',
            'status': 'ACTIVE',
            'createdAt': datetime.now().isoformat()
        }

        # Update deployment capacity
        logger.info(f"Updating capacity for deployment {deployment_id}")
        deployments_table.update_item(
            Key={'PK': deployment['PK'], 'SK': deployment['SK']},
            UpdateExpression='SET currentCapacity = currentCapacity + :val',
            ExpressionAttributeValues={':val': 1}
        )

        # Update cell capacity
        logger.info(f"Updating capacity for cell {cell_id}")
        cells_table.update_item(
            Key={'cellID': cell_id},
            UpdateExpression='SET currentCapacity = currentCapacity + :val',
            ExpressionAttributeValues={':val': 1}
        )

        # Register tenant
        logger.info(f"Registering tenant {tenant_id} in DynamoDB")
        tenants_table.put_item(
            Item=tenant_item,
            ConditionExpression=Attr('PK').not_exists()
        )

    except ClientError as e:
        logger.error(f"Error registering tenant {tenant_id}: {str(e)}")
        raise Exception("Error during tenant registration process")

    # Publish tenant registration event
    logger.info(f"Publishing registration event for tenant {tenant_id}")
    __create_control_plane_event(
        json.dumps(tenant_item),
        tenant_registration_detail_type
    )

    logger.info(f"Tenant registration completed successfully for tenant {tenant_id}")
    # Return success response
    return {
        "statusCode": 201,
        "body": json.dumps({
            "data": {
                "tenantId": tenant_id,
                "cellId": cell_id,
                "deploymentId": deployment_id,
                "deploymentType": deployment['type'],
                "tier": tier,
                "message": "Tenant registration successful"
            }
        })
    }
