```typescript
// bin/cell-based.ts
#!/usr/bin/env node
import * as cdk from 'aws-cdk-lib';
import { ControlPlaneStack } from '../lib/control-plane-stack';
import { CellStack } from '../lib/cell-stack';

import * as fs from 'fs';
import * as path from 'path';
import { ICell, ICellConfiguration } from '../lib/control- plane/cell-management/cell-configuration-interface';

// Read configuration from file
const cellConfig: ICellConfiguration = JSON.parse(
  fs.readFileSync(path.join(__dirname, "..", 'cell-configuration.json'), 'utf8')
);

// Control plane configuration 
const CONTROL_PLANE_ACCOUNT = process.env.CONTROL_PLANE_ACCOUNT || 'AWS_ACCOUNT';
const CONTROL_PLANE_REGION = process.env.CONTROL_PLANE_REGION || 'AWS_REGION';

const app = new cdk.App();

// Enable cross-account feature flags
app.node.setContext('@aws-cdk/core:enableCrossAccountEvents', true);
app.node.setContext('@aws-cdk/aws-events:eventsTargetLambda', true);

let controlPlane = new ControlPlaneStack(app, 'ControlPlaneStack', {
  env: { account: CONTROL_PLANE_ACCOUNT, region: CONTROL_PLANE_REGION },
  CellAccounts: cellConfig.cells.map(cell => cell.account),
  systemAdminEmail: process.env.SYSTEM_ADMIN_EMAIL || 'admin@example',
  cells: cellConfig.cells
});

const Cells = cellConfig.cells.map((cell: ICell) => {
  return new CellStack(app, `CellStack-${cell.name}`, {
    eventManager: controlPlane.eventManager,
    env: { account: cell.account, region: cell.region },
    controlPlaneAccount: CONTROL_PLANE_ACCOUNT,
    controlPlaneStack: controlPlane,
    table: controlPlane.table,
    cell: cell,
  });
});

// Add explicit dependency
Cells.forEach(appPlane => {
  appPlane.addDependency(controlPlane);
});

app.synth();

